DROP VIEW IF EXISTS evening_documentaries;
DROP TABLE IF EXISTS screenings;
DROP TABLE IF EXISTS cinemas;

CREATE TABLE cinemas (
    cinema_id    INTEGER PRIMARY KEY,
    cinema_name  VARCHAR(80) NOT NULL,
    screen_count INTEGER NOT NULL
);

CREATE TABLE screenings (
    screening_id INTEGER PRIMARY KEY,
    cinema_id    INTEGER NOT NULL REFERENCES cinemas (cinema_id),
    film_title   VARCHAR(120) NOT NULL,
    tickets_sold INTEGER NOT NULL,
    showtime     TIME NOT NULL
);

CREATE VIEW evening_documentaries AS
SELECT screening_id,
       cinema_id,
       film_title,
       tickets_sold,
       showtime
FROM screenings
WHERE film_title LIKE '%Documentary%'
  AND showtime >= '18:00:00';

INSERT INTO cinemas (cinema_id, cinema_name, screen_count) VALUES (1, 'Lumiere Arthouse', 3);
INSERT INTO cinemas (cinema_id, cinema_name, screen_count) VALUES (2, 'Grand Multiplex', 14);
INSERT INTO cinemas (cinema_id, cinema_name, screen_count) VALUES (3, 'Riverside Picturehouse', 2);
INSERT INTO cinemas (cinema_id, cinema_name, screen_count) VALUES (4, 'Old Town Screen', 1);
INSERT INTO cinemas (cinema_id, cinema_name, screen_count) VALUES (5, 'Metro Cineplex', 11);

INSERT INTO screenings (screening_id, cinema_id, film_title, tickets_sold, showtime)
    VALUES (1, 1, 'Deep Sea Drifters: A Documentary', 132, '20:15:00');
INSERT INTO screenings (screening_id, cinema_id, film_title, tickets_sold, showtime)
    VALUES (2, 1, 'Glacier Songs Documentary', 94, '19:00:00');
INSERT INTO screenings (screening_id, cinema_id, film_title, tickets_sold, showtime)
    VALUES (3, 3, 'Coal Valley Documentary', 101, '21:30:00');
INSERT INTO screenings (screening_id, cinema_id, film_title, tickets_sold, showtime)
    VALUES (4, 3, 'Coal Valley Documentary', 47, '14:00:00');
INSERT INTO screenings (screening_id, cinema_id, film_title, tickets_sold, showtime)
    VALUES (5, 2, 'Rocket Fever Documentary', 220, '20:45:00');

SELECT cinema_id,
       cinema_name,
       screen_count
FROM cinemas
WHERE screen_count > 10
ORDER BY screen_count DESC;

SELECT c.cinema_name,
       SUM(d.tickets_sold) AS total_tickets
FROM cinemas c
JOIN evening_documentaries d
  ON d.cinema_id = c.cinema_id
WHERE c.screen_count < 4
  AND d.tickets_sold > 80
GROUP BY c.cinema_name
ORDER BY total_tickets DESC;

