DROP TABLE IF EXISTS instructors;
DROP TABLE IF EXISTS departments;

CREATE TABLE departments (
    department_id   INTEGER PRIMARY KEY,
    department_name VARCHAR(60) NOT NULL,
    building        VARCHAR(40) NOT NULL
);

INSERT INTO departments (department_id, department_name, building) VALUES (1, 'History', 'Humanities');
INSERT INTO departments (department_id, department_name, building) VALUES (2, 'Philosophy', 'Humanities');
INSERT INTO departments (department_id, department_name, building) VALUES (3, 'Biology', 'Science');
INSERT INTO departments (department_id, department_name, building) VALUES (4, 'Chemistry', 'Science');
INSERT INTO departments (department_id, department_name, building) VALUES (5, 'Physics', 'Science');

SELECT department_id,
       department_name,
       building
FROM departments
WHERE building = 'Humanities'
ORDER BY department_name;

CREATE TABLE instructors (
    instructor_id   INTEGER PRIMARY KEY,
    department_id   INTEGER NOT NULL,
    instructor_name VARCHAR(60) NOT NULL,
    course_load     INTEGER NOT NULL,
    employment_type VARCHAR(20) NOT NULL,
    FOREIGN KEY (department_id) REFERENCES departments (department_id)
);

INSERT INTO instructors (instructor_id, department_id, instructor_name, course_load, employment_type)
     VALUES (101, 1, 'Marta Ellis', 4, 'Adjunct');
INSERT INTO instructors (instructor_id, department_id, instructor_name, course_load, employment_type)
     VALUES (102, 3, 'Devon Park', 5, 'Adjunct');
INSERT INTO instructors (instructor_id, department_id, instructor_name, course_load, employment_type)
     VALUES (103, 3, 'Ingrid Sole', 2, 'Adjunct');
INSERT INTO instructors (instructor_id, department_id, instructor_name, course_load, employment_type)
     VALUES (104, 4, 'Peter Naim', 6, 'Adjunct');
INSERT INTO instructors (instructor_id, department_id, instructor_name, course_load, employment_type)
     VALUES (105, 5, 'Lena Ortiz', 7, 'Tenured');

SELECT d.department_name AS department,
       MAX(i.course_load) AS heaviest_load
FROM departments AS d
JOIN instructors AS i
    ON i.department_id = d.department_id
WHERE d.building = 'Science'
  AND i.employment_type = 'Adjunct'
  AND i.course_load > 3
GROUP BY d.department_name
ORDER BY heaviest_load DESC;

