CREATE TABLE tournaments (
    tournament_id   INTEGER PRIMARY KEY,
    tournament_name VARCHAR(80) NOT NULL,
    prize_pool      DECIMAL(10, 2) NOT NULL,
    start_date      DATE NOT NULL
);

CREATE TABLE gaming_teams (
    team_id          INTEGER PRIMARY KEY,
    team_name        VARCHAR(60) NOT NULL,
    home_country     CHAR(2) NOT NULL,
    is_international SMALLINT NOT NULL
);

CREATE TABLE match_results (
    match_id         INTEGER PRIMARY KEY,
    tournament_id    INTEGER NOT NULL REFERENCES tournaments (tournament_id),
    home_team_id     INTEGER NOT NULL REFERENCES gaming_teams (team_id),
    away_team_id     INTEGER NOT NULL REFERENCES gaming_teams (team_id),
    winner_team_id   INTEGER NOT NULL REFERENCES gaming_teams (team_id),
    duration_minutes INTEGER NOT NULL
);

