INSERT INTO tournaments VALUES (2, 'Spring Open', 8000.00, '2024-03-02');
INSERT INTO tournaments VALUES (3, 'World Cup', 50000.00, '2024-06-20');

INSERT INTO gaming_teams VALUES (1, 'Dragons', 'KR', 1);
INSERT INTO gaming_teams VALUES (2, 'Phoenix', 'US', 1);
INSERT INTO gaming_teams VALUES (3, 'Wolves', 'DE', 0);
INSERT INTO gaming_teams VALUES (4, 'Titans', 'BR', 0);

INSERT INTO match_results VALUES (1, 1, 1, 2, 1, 38);
INSERT INTO match_results VALUES (2, 1, 1, 3, 1, 44);
INSERT INTO match_results VALUES (3, 1, 1, 4, 1, 41);
INSERT INTO match_results VALUES (4, 1, 2, 1, 1, 36);
INSERT INTO match_results VALUES (5, 1, 3, 1, 1, 40);
INSERT INTO match_results VALUES (6, 1, 4, 1, 1, 43);
INSERT INTO match_results VALUES (7, 1, 2, 3, 2, 39);
INSERT INTO match_results VALUES (8, 2, 3, 4, 3, 52);
INSERT INTO match_results VALUES (9, 3, 1, 2, 2, 55);
INSERT INTO match_results VALUES (10, 3, 2, 3, 2, 48);
INSERT INTO match_results VALUES (11, 3, 1, 4, 1, 47);

SELECT g.team_name,
       COUNT(*) AS wins
FROM match_results r
JOIN tournaments t
  ON t.tournament_id = r.tournament_id
JOIN gaming_teams g
  ON g.team_id = r.winner_team_id
WHERE t.prize_pool > 10000
GROUP BY g.team_id,
         g.team_name
HAVING COUNT(*) >= 5
ORDER BY wins DESC;

