INSERT INTO match_results VALUES (14, 4, 2, 4, 2, 49);

SELECT t.tournament_name,
       t.prize_pool,
       AVG(r.duration_minutes) AS avg_duration
FROM tournaments t
JOIN match_results r
  ON r.tournament_id = t.tournament_id
JOIN gaming_teams h
  ON h.team_id = r.home_team_id
JOIN gaming_teams a
  ON a.team_id = r.away_team_id
GROUP BY t.tournament_id,
         t.tournament_name,
         t.prize_pool
HAVING AVG(r.duration_minutes) > 45
   AND MAX(h.is_international + a.is_international) > 0
ORDER BY t.prize_pool DESC;

