-- Urban gargoyle registry: schema, sample data and the elevations() report.

CREATE TABLE buildings (
    building_id INTEGER PRIMARY KEY,
    building_name VARCHAR(60) NOT NULL,
    district VARCHAR(40) NOT NULL,
    arch_style VARCHAR(30) NOT NULL
);

INSERT INTO buildings VALUES (1, 'Grand Cathedral', 'Old Quarter', 'Gothic');
INSERT INTO buildings VALUES (2, 'Bell Tower of Saint Mure', 'Old Quarter', 'Gothic');
INSERT INTO buildings VALUES (3, 'Ironworks Exchange', 'Riverside', 'Brutalist');
INSERT INTO buildings VALUES (4, 'Chapel of Ashes', 'Hillcrest', 'Gothic');
INSERT INTO buildings VALUES (5, 'Glass Pavilion', 'Riverside', 'Modernist');

-- gothic_buildings: only the sites whose architecture invites gargoyles.
CREATE VIEW gothic_buildings AS
SELECT building_id,
       building_name,
       district
FROM buildings
WHERE arch_style = 'Gothic';

CREATE TABLE gargoyle_clans (
    clan_id INTEGER PRIMARY KEY,
    clan_name VARCHAR(40) NOT NULL,
    founding_year INTEGER
);

INSERT INTO gargoyle_clans VALUES (1, 'Obsidian', 1302);
INSERT INTO gargoyle_clans VALUES (2, 'Slatewing', 1418);
INSERT INTO gargoyle_clans VALUES (3, 'Emberclaw', 1550);

CREATE TABLE perches (
    perch_id INTEGER PRIMARY KEY,
    building_id INTEGER NOT NULL,
    clan_id INTEGER NOT NULL,
    perch_label VARCHAR(40) NOT NULL,
    elevation_feet INTEGER NOT NULL,
    roost_status VARCHAR(20) NOT NULL
);

INSERT INTO perches VALUES (1, 1, 1, 'North Spire Ledge', 250, 'occupied');
INSERT INTO perches VALUES (2, 1, 1, 'Nave Cornice', 180, 'occupied');
INSERT INTO perches VALUES (3, 1, 2, 'West Buttress', 214, 'occupied');
INSERT INTO perches VALUES (4, 2, 2, 'Belfry Crown', 305, 'occupied');
INSERT INTO perches VALUES (5, 2, 3, 'Clock Face Perch', 275, 'abandoned');
INSERT INTO perches VALUES (6, 3, 3, 'Smokestack Rim', 400, 'occupied');
INSERT INTO perches VALUES (7, 4, 3, 'Ossuary Gable', 232, 'occupied');
INSERT INTO perches VALUES (8, 4, 1, 'Crypt Eaves', 95, 'occupied');
INSERT INTO perches VALUES (9, 5, 2, 'Atrium Beam', 260, 'occupied');

-- elevations(): highest occupied roost per gothic site and clan, above 200 feet.
CREATE VIEW elevations AS
SELECT gothic_buildings.building_name,
       gargoyle_clans.clan_name,
       MAX(perches.elevation_feet) AS max_elevation_feet
FROM gothic_buildings
JOIN perches
  ON perches.building_id = gothic_buildings.building_id
JOIN gargoyle_clans
  ON gargoyle_clans.clan_id = perches.clan_id
WHERE perches.elevation_feet > 200
  AND perches.roost_status = 'occupied'
GROUP BY gothic_buildings.building_name,
         gargoyle_clans.clan_name;

SELECT building_name,
       clan_name,
       max_elevation_feet
FROM elevations
ORDER BY max_elevation_feet DESC;

