-- Koala digestion reporting module (PostgreSQL)

CREATE TABLE koalas (
    koala_id      integer PRIMARY KEY,
    forest_zone   text NOT NULL,
    health_status text NOT NULL
);

CREATE TABLE meals (
    meal_id         serial PRIMARY KEY,
    koala_id        integer NOT NULL REFERENCES koalas (koala_id),
    leaf_type       text NOT NULL,
    weight_grams    numeric(10, 2) NOT NULL,
    digestion_hours numeric(6, 2) NOT NULL
);

CREATE OR REPLACE FUNCTION tabulate(hours numeric)
returns TABLE (forest_zone text, total_weight numeric)
language plpgsql
AS $$
BEGIN
    IF hours IS NULL OR hours <= 0 THEN
        raise exception 'digestion limit must be a positive number, got %', hours;
    END IF;

    return query
    SELECT k.forest_zone,
           sum(m.weight_grams) AS total_weight
    FROM meals m
    JOIN koalas k
      ON k.koala_id = m.koala_id
    WHERE m.leaf_type = 'blue gum'
      AND m.digestion_hours < hours
    GROUP BY k.forest_zone
    HAVING count(DISTINCT m.meal_id) >= 3
    ORDER BY total_weight DESC;
END;
$$;

INSERT INTO koalas (koala_id, forest_zone, health_status) VALUES
    (1, 'northern', 'healthy'),
    (2, 'northern', 'healthy'),
    (3, 'southern', 'recovering'),
    (4, 'eastern',  'healthy');

INSERT INTO meals (koala_id, leaf_type, weight_grams, digestion_hours) VALUES
    (1, 'blue gum',  300.00, 2.50),
    (1, 'blue gum',  250.00, 3.75),
    (2, 'blue gum',  250.00, 1.50),
    (2, 'manna gum', 400.00, 2.00),
    (3, 'blue gum',  150.00, 3.00),
    (3, 'blue gum',  120.00, 2.25),
    (3, 'blue gum',  180.00, 6.00),
    (4, 'blue gum',  500.00, 5.50);

CREATE OR REPLACE FUNCTION format_digestion_report(hours numeric)
returns text
language plpgsql
AS $$
DECLARE
    report text := format('Blue gum intake digested in under %s hours', hours);
    row_out record;
BEGIN
    for row_out IN
        SELECT t.forest_zone,
               t.total_weight
        FROM tabulate(hours) t
    loop
        report := report || format(E'\n  %-10s %10s g', row_out.forest_zone, row_out.total_weight);
    END loop;

    return report;
END;
$$;

do $$
DECLARE
    heaviest text;
BEGIN
    raise notice '%', format_digestion_report(4);

    SELECT t.forest_zone
    INTO heaviest
    FROM tabulate(4) t
    LIMIT 1;

    raise notice 'heaviest zone: %', heaviest;
END;
$$;

