CREATE TABLE dogs (
    dog_id INTEGER PRIMARY KEY,
    dog_name VARCHAR(40) NOT NULL,
    breed VARCHAR(40) NOT NULL
);

CREATE TABLE race_segments (
    segment_id INTEGER PRIMARY KEY,
    race_id INTEGER NOT NULL,
    dog_id INTEGER NOT NULL,
    team_position VARCHAR(20) NOT NULL,
    pulling_force INTEGER NOT NULL,
    segment_distance INTEGER NOT NULL,
    FOREIGN KEY (dog_id) REFERENCES dogs (dog_id)
);

CREATE VIEW long_segments AS
SELECT
    segment_id,
    race_id,
    dog_id,
    team_position,
    pulling_force,
    segment_distance
FROM race_segments
WHERE segment_distance > 10;

INSERT INTO dogs (dog_id, dog_name, breed) VALUES (1, 'Balto', 'Husky');
INSERT INTO dogs (dog_id, dog_name, breed) VALUES (2, 'Togo', 'Husky');
INSERT INTO dogs (dog_id, dog_name, breed) VALUES (3, 'Nanook', 'Malamute');
INSERT INTO dogs (dog_id, dog_name, breed) VALUES (4, 'Sirius', 'Samoyed');

INSERT INTO race_segments VALUES (10, 3, 1, 'lead', 60, 15);
INSERT INTO race_segments VALUES (11, 3, 2, 'wheel', 14, 12);
INSERT INTO race_segments VALUES (12, 3, 3, 'lead', 45, 18);
INSERT INTO race_segments VALUES (13, 3, 4, 'lead', 55, 8);
INSERT INTO race_segments VALUES (14, 3, 2, 'lead', 70, 11);
INSERT INTO race_segments VALUES (15, 4, 1, 'wheel', 12, 20);
INSERT INTO race_segments VALUES (16, 4, 3, 'lead', 80, 25);

DELIMITER $$

CREATE PROCEDURE assess(IN race INTEGER)
BEGIN
    SELECT
        d.breed,
        SUM(s.segment_distance) AS total_distance
    FROM long_segments AS s
    JOIN dogs AS d
        ON s.dog_id = d.dog_id
    WHERE s.race_id = race
        AND s.team_position = 'lead'
        AND s.pulling_force >= 50
    GROUP BY d.breed
    ORDER BY total_distance DESC;

    SELECT DISTINCT d.dog_name
    FROM race_segments AS s
    JOIN dogs AS d
        ON s.dog_id = d.dog_id
    WHERE s.race_id = race
        AND s.team_position = 'wheel'
        AND s.pulling_force < 20
        AND d.breed = 'Husky'
    ORDER BY d.dog_name;
END$$

DELIMITER ;

CALL assess(3);
CALL assess(4);

