CREATE TABLE buggies (
    buggy_id INTEGER PRIMARY KEY,
    model VARCHAR(50) NOT NULL,
    tire_type VARCHAR(20) NOT NULL
);

CREATE TABLE race_logs (
    log_id INTEGER PRIMARY KEY,
    tournament INTEGER NOT NULL,
    buggy_id INTEGER NOT NULL,
    wind_speed DECIMAL(5, 2) NOT NULL,
    traction_coefficient DECIMAL(4, 2) NOT NULL,
    wheel_sinkage DECIMAL(4, 2) NOT NULL,
    FOREIGN KEY (buggy_id) REFERENCES buggies (buggy_id)
);

INSERT INTO buggies (buggy_id, model, tire_type) VALUES (1, 'Peter Lynn Folding', 'slick');
INSERT INTO buggies (buggy_id, model, tire_type) VALUES (2, 'Libre Vmax', 'knobby');
