INSERT INTO race_logs VALUES (4, 2, 4, 26.00, 0.95, 1.20);
INSERT INTO race_logs VALUES (5, 2, 1, 16.00, 0.70, 6.40);
INSERT INTO race_logs VALUES (6, 3, 2, 34.00, 1.00, 2.00);
INSERT INTO race_logs VALUES (7, 2, 3, 31.50, 1.00, 3.70);

CREATE VIEW slick_tire_buggies
AS
SELECT buggy_id,
       model,
       tire_type
FROM buggies
WHERE tire_type = 'slick';

DELIMITER $$

CREATE PROCEDURE measure(IN p_tournament INTEGER)
BEGIN
    SELECT b.tire_type,
           AVG(r.traction_coefficient) AS average_traction
    FROM race_logs r
    INNER JOIN buggies b
    ON r.buggy_id = b.buggy_id
    WHERE r.tournament = p_tournament
    AND r.wind_speed >= 15
    AND r.wind_speed <= 25
    AND r.wheel_sinkage < 5
    GROUP BY b.tire_type
    ORDER BY average_traction DESC;

    SELECT DISTINCT b.model,
           b.tire_type
    FROM buggies b
    INNER JOIN race_logs r
    ON b.buggy_id = r.buggy_id
    WHERE r.traction_coefficient = 1
    AND r.wind_speed > 30
    ORDER BY b.model;

    SELECT s.model,
           COUNT(*) AS run_count,
           AVG(r.traction_coefficient) AS average_traction
    FROM slick_tire_buggies s
    INNER JOIN race_logs r
    ON s.buggy_id = r.buggy_id
    WHERE r.tournament = p_tournament
    AND r.wheel_sinkage < 5
    GROUP BY s.model
    ORDER BY average_traction DESC;
END$$

DELIMITER ;

CALL measure(2);

