CREATE TABLE instruments (
    instrument_id INTEGER PRIMARY KEY,
    serial_number VARCHAR(20) NOT NULL,
    wood_type VARCHAR(20) NOT NULL
);

CREATE TABLE maintenance_logs (
    log_id INTEGER PRIMARY KEY,
    instrument_id INTEGER NOT NULL,
    session_id INTEGER NOT NULL,
    wheel_speed INTEGER NOT NULL,
    rosin_type VARCHAR(10) NOT NULL,
    friction_resistance INTEGER NOT NULL
);

INSERT INTO instruments (instrument_id, serial_number, wood_type) VALUES (1, 'MP-1001', 'maple');
