INSERT INTO maintenance_logs VALUES (1, 1, 8, 120, 'dark', 5);
INSERT INTO maintenance_logs VALUES (2, 2, 8, 140, 'dark', 3);
INSERT INTO maintenance_logs VALUES (3, 2, 8, 90, 'light', 0);
INSERT INTO maintenance_logs VALUES (4, 3, 8, 155, 'dark', 7);
INSERT INTO maintenance_logs VALUES (5, 4, 8, 100, 'dark', 2);
INSERT INTO maintenance_logs VALUES (6, 4, 8, 75, 'light', 0);
INSERT INTO maintenance_logs VALUES (7, 1, 9, 180, 'dark', 4);

CREATE VIEW maple_instruments AS
SELECT instrument_id,
       serial_number,
       wood_type
FROM instruments
WHERE wood_type = 'maple';

DELIMITER //

CREATE PROCEDURE evaluate(IN session INTEGER)
BEGIN
    SELECT instruments.wood_type,
           COUNT(*) AS dark_high_speed_logs
    FROM instruments
    JOIN maintenance_logs
        ON maintenance_logs.instrument_id = instruments.instrument_id
    WHERE maintenance_logs.session_id = session
        AND maintenance_logs.rosin_type = 'dark'
        AND maintenance_logs.wheel_speed > 100
    GROUP BY instruments.wood_type
    ORDER BY dark_high_speed_logs DESC;

    SELECT instruments.serial_number,
           instruments.wood_type,
           maintenance_logs.wheel_speed
    FROM instruments
    JOIN maintenance_logs
        ON maintenance_logs.instrument_id = instruments.instrument_id
    WHERE maintenance_logs.session_id = session
        AND maintenance_logs.rosin_type = 'light'
        AND maintenance_logs.friction_resistance = 0
    ORDER BY instruments.serial_number;

    SELECT maple_instruments.serial_number,
           COUNT(*) AS dark_high_speed_logs,
           MAX(maintenance_logs.wheel_speed) AS top_wheel_speed
    FROM maple_instruments
    JOIN maintenance_logs
        ON maintenance_logs.instrument_id = maple_instruments.instrument_id
    WHERE maintenance_logs.session_id = session
        AND maintenance_logs.rosin_type = 'dark'
        AND maintenance_logs.wheel_speed > 100
    GROUP BY maple_instruments.serial_number
    ORDER BY dark_high_speed_logs DESC;
END //

DELIMITER ;

CALL evaluate(8);

